import{_ as a,o as r,c as t,ag as s}from"./chunks/framework.DPTJCqgd.js";const b=JSON.parse('{"title":"开始使用 Harness Desktop","description":"","frontmatter":{"editSource":"docs/user/guide/index.zh.md","editSourceUrl":"https://github.com/Bestbbb/deepseek-harness-desktop/edit/main/docs/user/guide/index.zh.md"},"headers":[],"relativePath":"guide/quickstart.md","filePath":"guide/quickstart.md"}'),o={name:"guide/quickstart.md"};function n(i,e,l,p,d,h){return r(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="开始使用-harness-desktop" tabindex="-1">开始使用 Harness Desktop <a class="header-anchor" href="#开始使用-harness-desktop" aria-label="Permalink to &quot;开始使用 Harness Desktop&quot;">​</a></h1><p>使用 Harness Desktop 连接模型，并在本地项目中运行任务。本指南面向安装包用户：应用会自行启动 Harness 运行时，无需手动启动 Web 服务器或单独安装 CLI（命令行界面）。如果需要从源码开发，请参阅<a href="https://github.com/Bestbbb/deepseek-harness-desktop/blob/main/README.zh.md#run-from-source" target="_blank" rel="noreferrer">构建说明</a>。</p><h2 id="安装并打开应用" tabindex="-1">安装并打开应用 <a class="header-anchor" href="#安装并打开应用" aria-label="Permalink to &quot;安装并打开应用&quot;">​</a></h2><ol><li>打开 <a href="https://github.com/Bestbbb/deepseek-harness-desktop/releases/tag/desktop-v0.1.3-alpha.1" target="_blank" rel="noreferrer">Releases</a>，在 <strong>Assets</strong> 中选择 macOS Apple Silicon DMG 或 Windows x64 安装包。检查该版本内置的 Harness 版本和平台说明；源码可能比公开安装包更新。</li><li>安装前，使用该版本的 SHA-256 校验和核验下载文件。这些社区预览包在 macOS 上使用临时签名且未经公证，在 Windows 上未签名。如果操作系统阻止应用运行，请先阅读发布页的平台说明，再决定是否允许打开。</li><li>打开 <strong>Harness Desktop</strong>，等待会话界面出现。阅读首次运行提示后，再继续配置模型。</li></ol><p>自动更新尚未配置，请到 Releases 检查新版安装包。<a href="https://github.com/Bestbbb/deepseek-harness-desktop/blob/main/apps/desktop/README.zh.md" target="_blank" rel="noreferrer">桌面指南</a>介绍数据隔离方式与分发限制。</p><h2 id="配置模型" tabindex="-1">配置模型 <a class="header-anchor" href="#配置模型" aria-label="Permalink to &quot;配置模型&quot;">​</a></h2><p>打开<strong>设置 → 模型</strong>。在 DeepSeek 卡片中输入 <a href="https://platform.deepseek.com/" target="_blank" rel="noreferrer">DeepSeek API 密钥</a>，或通过<strong>添加提供方</strong>、<strong>添加自定义提供方</strong>配置其他受支持的提供方或网关。保存配置，然后在会话输入框的模型选择器中选择模型。</p><p><a href="./providers">模型配置指南</a>介绍认证、模型探测、图片支持和网关设置。保存密钥只是将其存储在本地，并不证明提供方会接受请求。模型请求使用你所选提供方的服务与计费，不包含附赠订阅。</p><h2 id="选择工作区" tabindex="-1">选择工作区 <a class="header-anchor" href="#选择工作区" aria-label="Permalink to &quot;选择工作区&quot;">​</a></h2><p>点击<strong>选择工作区</strong>，添加并选中本地项目目录。会话输入框需要选定工作区和模型后才能发送任务。请先选择一个你愿意授权 agent（智能体）访问的项目。</p><h2 id="运行任务" tabindex="-1">运行任务 <a class="header-anchor" href="#运行任务" aria-label="Permalink to &quot;运行任务&quot;">​</a></h2><p>新建会话，选择 Agent 预设，并发送一个小任务：</p><blockquote><p>Summarize this repository and identify its main packages.</p></blockquote><p>Agent 可以读取和编辑工作区文件、运行命令、委派工作并维护计划。如果根据当前权限策略，某项操作需要审批，Web UI 会先询问你。</p><p>在要求更大范围的修改前，先阅读回复与工具结果。如果提供方拒绝请求，请返回<strong>设置 → 模型</strong>，按照<a href="./providers#provider-troubleshooting">故障排查指南</a>检查端点、模型和凭据。如果输入框不可用，也需要检查工作区和模型是否已选择。</p><h2 id="继续使用" tabindex="-1">继续使用 <a class="header-anchor" href="#继续使用" aria-label="Permalink to &quot;继续使用&quot;">​</a></h2><ul><li><a href="./providers">配置模型</a></li><li><a href="./network-proxy">配置网络代理</a></li><li><a href="./python-sdk">使用 Python SDK</a></li><li><a href="./../develop/basic/">开发插件</a></li></ul>',17)])])}const u=a(o,[["render",n]]);export{b as __pageData,u as default};
